INSERT INTO checklist_item (id, grupo_id, titulo, o_que_e, por_que, como_fazer, online, documentos, prazo, perfil, pagina_rota, ordem) VALUES
  ('ubs-cartao-sus', 'saude', 'Encontre a sua UBS e faça o Cartão SUS', 'As Unidades Básicas de Saúde (UBS) fazem consultas, vacinas e exames básicos. Elas também emitem o Cartão SUS.', 'É pela UBS que você marca consultas e recebe vacinas e remédios da rede pública.', 'Vá a uma UBS com seus documentos e peça a emissão ou atualização do Cartão SUS. A Prefeitura não publica qual UBS atende cada bairro: o site mostra a mais próxima, e a própria UBS confirma se ela é a de referência do seu endereço.', FALSE, NULL, NULL, NULL, '/meu-bairro', 1),
  ('creche', 'educacao', 'Inscreva a criança na creche municipal', 'Inscrição para vaga em creche da rede municipal, a partir dos 4 meses completos da criança.', 'As vagas são distribuídas a partir das inscrições: quanto antes, melhor.', 'A inscrição pode ser feita em qualquer creche, de preferência na mais próxima de casa (Secretaria de Educação). Segundo a imprensa (setembro/2026), as inscrições de creche para 2027 vão de 05/10 a 15/12/2026; confirme na creche.', FALSE, NULL, 'Para 2027: 05/10 a 15/12/2026, segundo a imprensa — confirme na creche.', 'criancas', '/meu-bairro', 2),
  ('escola', 'educacao', 'Matrícula ou transferência para escola municipal (EMEB)', 'Inscrição na pré-escola ou no ensino fundamental da rede municipal, ou transferência de outra cidade.', 'Garante a vaga na escola mais perto da nova casa.', 'Procure a escola de interesse. Com o endereço novo atualizado, a inscrição é feita como transferência (Secretaria de Educação). Segundo a imprensa (setembro/2026), as inscrições de pré-escola e fundamental para 2027 terminaram em 18/09; novas inscrições a partir de 08/01/2027, conforme as vagas.', FALSE, NULL, 'Para 2027, novas inscrições a partir de 08/01/2027, segundo a imprensa — confirme na escola.', 'criancas', '/meu-bairro', 3),
  ('agua', 'casa', 'Passe a conta de água para o seu nome (SAAE)', 'Alteração da titularidade da ligação de água e esgoto no SAAE de Indaiatuba.', 'A conta e os avisos chegam em nome de quem mora no imóvel.', 'Pelo serviço online do SAAE (sem login): preencha os dados e anexe os documentos. Para inquilino, use o serviço "Alteração de inquilino responsável".', TRUE, 'Escritura, matrícula ou contrato de compra e venda; CPF e RG; Formulário de autorização do SAAE (ou o de herdeiros, em caso de falecimento do proprietário); Arquivos em PDF ou imagem, até 10 MB cada', '10 dias úteis (SAAE).', NULL, NULL, 4),
  ('energia', 'casa', 'Passe a conta de luz para o seu nome (CPFL)', 'Troca de titularidade da conta de energia. Em Indaiatuba, a distribuidora é a CPFL (CPFL Piratininga, segundo a imprensa).', 'A conta passa a sair no seu nome, e você responde só pelo consumo a partir da mudança.', 'Pelo site ou pelos canais da CPFL. Os documentos e o passo a passo estão na página oficial de troca de titularidade.', TRUE, NULL, NULL, NULL, NULL, 5),
  ('iptu', 'casa', 'IPTU: atualize o endereço do carnê e ative o IPTU Digital', 'O IPTU é cobrado anualmente pela Prefeitura. Dá para receber o carnê por e-mail (IPTU Digital) e emitir as guias pelo portal Minha Indaiatuba.', 'Sem o endereço atualizado, o carnê pode não chegar e a parcela atrasar (com multa e juros).', 'Para mudar o endereço ou o responsável pelo carnê, fale com o Departamento de Cadastro Imobiliário: engenharia.entrega@indaiatuba.sp.gov.br ou (19) 3834-9181. Para o IPTU Digital, preencha o formulário de cadastramento de e-mail.', TRUE, NULL, 'Pedidos feitos até 28 de novembro valem para o carnê do ano seguinte (Prefeitura).', NULL, NULL, 6),
  ('coleta', 'casa', 'Descubra o dia da coleta de lixo', 'Coleta domiciliar de lixo e pontos de entrega de recicláveis (Ilhas Ecológicas).', 'Lixo na calçada fora do dia e do horário se acumula e atrapalha a coleta.', 'Coloque o lixo só no dia e no horário do seu bairro. Período diurno: de segunda a sábado, a partir das 6h. Período noturno: de segunda a sexta a partir das 17h e aos sábados a partir das 16h. A Prefeitura publica a lista dos locais que mudaram de programação em 2026; para os demais, informe-se na SEMURB: (19) 3825-5410.', FALSE, NULL, NULL, NULL, '/meu-bairro', 7),
  ('iluminacao', 'casa', 'Saiba como pedir conserto de iluminação pública', 'Lâmpada de poste apagada ou piscando na sua rua.', 'O pedido é feito pela internet, sem precisar ir à Prefeitura.', 'Registre o pedido no sistema de atendimento da iluminação pública (Geolux), linkado pela Prefeitura.', TRUE, NULL, NULL, NULL, NULL, 8),
  ('titulo-eleitor', 'documentos', 'Transfira o título de eleitor para Indaiatuba', 'Mudança do domicílio eleitoral para votar em Indaiatuba.', 'Você passa a votar na nova cidade e evita viajar ou justificar a ausência.', 'Pelo Autoatendimento Eleitoral do TSE, no serviço "Transferir título eleitoral" (o próprio serviço lista os documentos). A lei eleitoral não recebe pedidos de transferência nos 150 dias antes de uma eleição.', TRUE, NULL, 'Fechado nos 150 dias anteriores a cada eleição (Lei 9.504/1997, art. 91).', NULL, NULL, 9),
  ('cnh-veiculo', 'documentos', 'Atualize o endereço da CNH e do veículo', 'Alteração de endereço no cadastro do Detran-SP (habilitação e veículo).', 'Multas e avisos chegam no endereço cadastrado.', 'No portal do Detran-SP (entrando com a conta gov.br), procure "Alteração de endereço" na área de habilitação e na de veículos. Se o serviço online não atender o seu caso, agende no Poupatempo.', TRUE, NULL, NULL, 'carro', NULL, 10),
  ('junta-militar', 'documentos', 'Comunique a mudança à Junta Militar (se tiver obrigação militar)', 'Transferência de residência no cadastro do serviço militar.', 'A Prefeitura orienta que qualquer mudança de residência seja comunicada à junta de serviço militar mais próxima, assim que ocorrer.', 'A Junta de Serviço Militar de Indaiatuba (no Ponto Cidadão) faz a transferência pelo sistema do Exército e regulariza a situação militar. Telefone: (19) 3816-9267.', FALSE, NULL, 'Assim que a mudança ocorrer (Prefeitura).', NULL, '/cidadania/ponto-cidadao', 11),
  ('minha-indaiatuba', 'cidade', 'Crie o acesso ao portal Minha Indaiatuba', 'Portal de serviços online da Prefeitura (IPTU, certidões, solicitações), com login pela conta gov.br.', 'Muita coisa da Prefeitura se resolve por ele, sem ir a um balcão.', 'Entre no portal com a conta gov.br. A Prefeitura tem um tutorial de acesso.', TRUE, NULL, NULL, NULL, NULL, 12),
  ('telefones', 'cidade', 'Salve os telefones úteis no celular', 'Emergências (192, 190, 193, 153, 199), Disque Prefeitura, Ouvidoria e SAAE.', 'A central telefônica da Prefeitura é o Disque Prefeitura (19) 3834-9000, e reclamações vão para a Ouvidoria, 0800 770 7702.', 'Abra a página de telefones úteis e salve os números que você mais vai usar.', TRUE, NULL, NULL, NULL, '/contatos', 13),
  ('cartao-sou', 'cidade', 'Faça o cartão SOU do ônibus', 'Cartão do transporte coletivo municipal (SOU Indaiatuba).', 'A primeira via é gratuita, e o cartão é recarregado para usar nos ônibus.', 'No guichê da SOU Indaiatuba, no Ponto Cidadão (Rua Vinte e Quatro de Maio, 1.670), de segunda a sexta, das 9h às 17h. Telefone (19) 3518-7808, WhatsApp (19) 97414-9323.', FALSE, 'RG; CPF; Comprovante de endereço', NULL, NULL, '/mobilidade', 14),
  ('castracao', 'pets', 'Cadastre seu cão ou gato para castração gratuita', 'O Centro de Reabilitação Animal da Prefeitura faz castração gratuita de cães e gatos de moradores da cidade.', 'Castração gratuita para animais de moradores de Indaiatuba.', 'Cadastro de castração de segunda a sexta, das 10h às 16h, no Centro de Reabilitação Animal (Rua Safira, 120). Telefone (19) 3936-2782.', FALSE, NULL, NULL, 'pet', NULL, 15),
  ('vacina-raiva', 'pets', 'Vacina contra raiva para cães e gatos', 'Vacinação antirrábica oferecida pela Prefeitura, com inscrição pelo site.', 'A vacina contra a raiva protege o animal e a família.', 'Acompanhe a página de inscrição da Vigilância Epidemiológica. Em 08/10/2026 as vagas estavam preenchidas, com aviso de novas inscrições em breve.', TRUE, NULL, NULL, 'pet', NULL, 16);

